INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Iridescence', 'Explore a serene island where land and sea intertwine on your quest to help a mysterious girl from the sea find her way home. Uncover rich mythology and hidden truths in this heart-warming, epic tale, brought to life with gorgeous artwork and music. Embark on a truly unforgettable adventure!' FROM games WHERE igdb_id = 329810 ON CONFLICT (game_id, language_code) DO NOTHING;
