INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heritage: A Dragon''s Tale', 'It was a day like any other in the Skybound Isles when a dark mass arose from the clouds that separated the forgotten and dangerous world below from the home of the dragons above. General Mechos, a powerful military leader of the humans launched an attack on the floating islands and abducted the dragoness Crystal for reasons unknown.
