INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'End Gate: The Last Passenger', 'You wake up, alone, in a hypersleep box, with no memories left. You find yourself in an enormous space station, orbiting with a strange asteroid, around a gigantic black hole. And now, it''s time to search, everywhere, to understand who you were. And most importantly, what''s left to do here.' FROM games WHERE igdb_id = 311612 ON CONFLICT (game_id, language_code) DO NOTHING;
