INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pink Pong', 'Pink Pong is a classic arcade-style game where two players compete in a fast-paced and skillful showdown. Take control of your paddle and go head-to-head with your opponent in a thrilling battle of reflexes and precision. Use your paddle to bounce the ball past your adversary and score points, but be on guard - they''re aiming to do the same! The first player to reach the target score wins. Enjoy the timeless simplicity and competitive fun of this classic arcade game brought to the digital age. Pink Pong is perfect for quick matches and high-energy gaming sessions.' FROM games WHERE igdb_id = 287585 ON CONFLICT (game_id, language_code) DO NOTHING;
