INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Pair of Feathers Squawk Together', '"A Pair Of Feathers Squawk Together" is an easy-to-play, challenging-to-beat platformer inspired by the likes of Jump King and Bread & Fred. Flap the Parrot only has two controls: a right flap, to flap to the right, and a left flap, to flap to the left. As you get higher up the island, you''ll encounter new regions with new gimmicks and traps to be wary of. Avoid getting sent back to the ocean down below, and find the treasure at the peak!' FROM games WHERE igdb_id = 311607 ON CONFLICT (game_id, language_code) DO NOTHING;
