INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mercurial Dreams', 'In ''Mercurial Dreams,'' you''re a cat plush toy whose mind mysteriously entwines with that of your young owner, a kid, shielding him from bad dreams. The game is set in ''Mercurial Village'', a weird place with a river made of mercury and strange buildings. Your job is to keep the kid safe from scary dreams by playing mini-games and completing tasks inside strange buildings. ''Mercurial Dreams'' is all about adventure, mystery, and being a hero in a dream world.' FROM games WHERE igdb_id = 323300 ON CONFLICT (game_id, language_code) DO NOTHING;
