INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Village Cult', 'The events take place in a Soviet forest village located far from civilization. The main character inherits a house. Soon the hero learns that the entire village is part of a cult. Those who sacrifice people and engage in cannibalism. The hero has to get out of the village. But can he?' FROM games WHERE igdb_id = 309452 ON CONFLICT (game_id, language_code) DO NOTHING;
