INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Turbo Sliders Unlimited', 'Turbo Sliders Unlimited is a spiritual successor of many classic top-down racing games, but in 3D and with modern online features and extensive customization and modding possibilities. It goes far beyond being just a racing game - it is a community driven platform where anyone can create their own levels, vehicles and game modes. It can be played as a serious esports game or as a fun casual game. It can be played alone, as online multiplayer or as local multiplayer.' FROM games WHERE igdb_id = 188595 ON CONFLICT (game_id, language_code) DO NOTHING;
