INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infinity Slime Dungeon', 'Infinity Slime Dungeon is an Idle RPG roguelite where you guide Jeffrey the Slime on his quest for freedom! Face off against 15 unique enemies in endless waves, collecting souls from each victory to upgrade Jeffrey’s stats and abilities. After every battle, you’ll make a crucial choice: restart and strengthen Jeffrey further with his earned souls, or forge ahead to the next foe, risking it all for greater rewards. Push Jeffrey to new heights—or depths—in his escape!' FROM games WHERE igdb_id = 321754 ON CONFLICT (game_id, language_code) DO NOTHING;
