INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thou Shalt Not Kill', '"Thou Shalt Not Kill" is a VHS-style first-person walking simulator horror game. You play as Angel, a girl traveling through the forest who finds a VHS tape lying on the ground. She starts watching it, only to discover that the footage is unsettling and tells a mysterious story. As you watch the entire tape, you realize this is no ordinary VHS footage, and you are shocked by its revelations.' FROM games WHERE igdb_id = 312220 ON CONFLICT (game_id, language_code) DO NOTHING;
