INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fractured Veil', 'Fractured Veil is a persistent, multiplayer, survival-RPG game set in beautiful but deadly Maui, 100 years from now after a globe and dimension spanning catastrophe left the world fractured. Live out the apocalypse in paradise in the remains of Maui. Build your base, explore, craft, survive, and keep an aloha state of mind.' FROM games WHERE igdb_id = 83357 ON CONFLICT (game_id, language_code) DO NOTHING;
