INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'I Am Cat', '"I Am Cat" is a VR sandbox adventure game where players step into the role of a cat living in Granny''s house. Explore the house, interact with its environments, and complete cat-themed quests. The game offers free-form exploration, physics-based interactions, and mini-games, allowing players to solve puzzles, play games, and create mischief. Whether sneaking around, uncovering secrets, or causing chaos, the choice is yours.' FROM games WHERE igdb_id = 303244 ON CONFLICT (game_id, language_code) DO NOTHING;
